function onProvince(id){let p=provinces.find(x=>x.id===id);if(!p)return;if(attackMode){let from=provinces.find(x=>x.id===selected);if(p.owner==='aurora'||!from||from.owner!=='aurora'||!adjacent(from,p)){notify('Escolha um território inimigo adjacente.');return}if(!isWar('aurora',p.owner)){notify('Declare guerra antes de iniciar uma ofensiva.');return}if(from.units<1){notify('Não há divisões disponíveis nesta província.');return}if(orders.some(o=>o.from===from.id)){notify('Esta província já está empenhada numa ofensiva.');return}orders.push({from:from.id,to:p.id,progress:0});attackMode=false;log(`Ofensiva lançada de ${from.name} em direção a ${p.name}.`,'alert');notify('Ordem de ataque enviada.');selected=from.id;renderAll();return}selected=id;activeTab='province';document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab==='province'));renderMap();renderSide()}
function declareWar(target){if(isWar('aurora',target)){notify('A guerra já está em andamento.');return}wars.push(['aurora',target]);log(`Aurora declarou guerra ao ${nations[target].name}.`,'alert');notify(`Guerra declarada contra ${nations[target].short}.`);renderAll()}
function recruit(p){let n=nations.aurora;if(n.manpower<8||n.industry<3)return;n.manpower-=8;n.industry-=3;p.units++;log(`Uma nova divisão foi mobilizada em ${p.name}.`);notify('Divisão mobilizada.');renderAll()}
function setFocus(name){if(focus===name){notify('Este foco já está ativo.');return}focus=name;focusStart=tickCount;log(`Aurora iniciou o foco nacional: ${name}.`);renderSide()}
function research(id){let t=researchTechs.find(x=>x.id===id),n=nations.aurora;if(!t||researched.includes(id)||n.research<t.cost)return;n.research-=t.cost;researched.push(id);if(id==='logistica')log('Nova doutrina logística acelera nossas ofensivas.');if(id==='industria'){n.industry+=5;log('A indústria de precisão aumentou nossa capacidade produtiva.')}if(id==='doutrina')log('A doutrina defensiva fortalece nossas guarnições.');notify(`${t.name} pesquisada.`);renderAll()}
let focusStart=0;function advanceDate(){dateDay++;let days=[31,28,31,30,31,30,31,31,30,31,30,31];if(dateDay>days[dateMonth]){dateDay=1;dateMonth++;if(dateMonth>11){dateMonth=0;dateYear++}}}
function tick(){if(speed===0||gameEnded)return;tickCount++;advanceDate();let playerFactories=ownProvinces('aurora').reduce((s,p)=>s+p.factories,0);nations.aurora.industry=Math.min(35,nations.aurora.industry+Math.max(.15,playerFactories*.035));nations.aurora.research+=playerFactories*.025;
if(focus&&tickCount-focusStart>=14){if(focus==='Rearmamento industrial')nations.aurora.industry+=4;if(focus==='Alistamento patriótico')nations.aurora.manpower+=18;if(focus==='Unidade nacional')nations.aurora.stability=Math.min(100,nations.aurora.stability+15);log(`Foco nacional concluído: ${focus}.`);focus=null}
// Orders resolve as rolling battles; each side loses cohesion over time.
orders=orders.filter(o=>{let a=provinces.find(p=>p.id===o.from),d=provinces.find(p=>p.id===o.to);if(!a||!d||a.owner!=='aurora'||!isWar('aurora',d.owner)||a.units<=0)return false;let attackBonus=researched.includes('logistica')?1.15:1,defBonus=researched.includes('doutrina')&&d.owner==='aurora'?1.25:1;let force=Math.max(.4,(a.units/d.units)*attackBonus/defBonus);o.progress+=Math.max(8,Math.min(29,13+force*5));if(tickCount%4===0&&a.units>1)a.units--;if(tickCount%5===0&&d.units>1)d.units--;if(o.progress>=100){let oldOwner=d.owner;d.owner='aurora';d.units=Math.max(1,a.units);a.units=Math.max(0,a.units-1);nations.aurora.manpower+=Math.floor(d.manpower*.6);log(`${nations[oldOwner].short} perdeu ${d.name}; território sob controle de Aurora.`,'alert');return false}if(o.progress>=65&&Math.random()<.24){notify(`Combates intensos em ${d.name} — ${Math.round(o.progress)}%`)}return true});
// Opponents counterattack while at war. Orders are deliberately limited to one per province.
if(tickCount%3===0){for(let w of wars){let foe=w[0]==='aurora'?w[1]:w[0];let borders=provinces.filter(p=>p.owner===foe&&p.units>0&&!orders.some(o=>o.from===p.id)).flatMap(p=>provinces.filter(q=>q.owner==='aurora'&&adjacent(p,q)&&!orders.some(o=>o.to===q.id)).map(q=>({from:p,to:q})));if(borders.length&&Math.random()<.68){let pick=borders[Math.floor(Math.random()*borders.length)];orders.push({from:pick.from.id,to:pick.to.id,progress:0,ai:true})}}}
orders=orders.filter(o=>{if(!o.ai)return true;let a=provinces.find(p=>p.id===o.from),d=provinces.find(p=>p.id===o.to);if(!a||!d||a.owner===d.owner||!isWar(a.owner,d.owner)||a.units<=0)return false;o.progress+=Math.max(7,12+(a.units/d.units)*4);if(tickCount%4===0&&a.units>1)a.units--;if(tickCount%5===0&&d.units>1)d.units--;if(o.progress>=100){let former=d.owner;d.owner=a.owner;d.units=Math.max(1,a.units);a.units=Math.max(0,a.units-1);log(`${nations[former].short} perdeu ${d.name} para ${nations[a.owner].short}.`,'alert');return false}return true});
if(tickCount%4===0){for(let id of Object.keys(nations)){if(id!=='aurora'){let f=ownProvinces(id).reduce((s,p)=>s+p.factories,0);nations[id].manpower=Math.min(100,nations[id].manpower+f*.08)}}}
if(tickCount%5===0&&Math.random()<.18)log(['A tensão cresce nas chancelarias de Edria.','Relatórios indicam movimentação militar nas fronteiras.','A imprensa de Aurora pede cautela e unidade.'][Math.floor(Math.random()*3)]);
checkEnd();renderAll()}
function checkEnd(){let count=ownProvinces('aurora').length;if(count===0)endGame(false);else if(count>=10)endGame(true)}
function endGame(win){gameEnded=true;speed=0;$('#endingTitle').textContent=win?'Vitória em Edria':'A república caiu';$('#endingText').textContent=win?`Aurora consolidou ${ownProvinces('aurora').length} províncias e definiu o destino do continente. A campanha será lembrada por gerações.`:'As forças de Aurora foram derrotadas. A história de Edria seguirá sem a república.';$('#gameover').classList.add('show')}
let toastTimer;function notify(msg){let el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2100)}
function openResearch(){activeTab='research';document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab==='research'));renderSide();$('#researchList').innerHTML=researchTechs.map(t=>`<div class="research-card"><div class="research-icon">${t.icon}</div><div class="research-info"><strong>${t.name}</strong><small>${researched.includes(t.id)?'Concluída':t.desc}</small></div><button data-modal-tech="${t.id}" ${researched.includes(t.id)||nations.aurora.research<t.cost?'disabled':''}>${researched.includes(t.id)?'FEITA':t.cost+' ◈'}</button></div>`).join('');$('#modal').classList.add('show');$('#researchList').querySelectorAll('[data-modal-tech]').forEach(b=>b.onclick=()=>{research(b.dataset.modalTech);openResearch()})}
document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>{activeTab=t.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===t));renderSide()}));
document.querySelectorAll('.speed-btn').forEach(b=>b.addEventListener('click',()=>{speed=Number(b.dataset.speed);document.querySelectorAll('.speed-btn').forEach(x=>x.classList.toggle('active',x===b));$('#pause').textContent=speed===0?'Retomar':'Pausar'}));$('#pause').onclick=()=>{speed=speed===0?1:0;document.querySelectorAll('.speed-btn').forEach(x=>x.classList.toggle('active',Number(x.dataset.speed)===speed));$('#pause').textContent=speed===0?'Retomar':'Pausar'};$('#mapMode').onclick=()=>{$('#mapMode').classList.toggle('active');renderMap()};$('#labelsToggle').onclick=()=>{labelsOn=!labelsOn;$('#labelsToggle').classList.toggle('active',labelsOn);renderMap()};$('#closeModal').onclick=()=>$('#modal').classList.remove('show');$('#modal').onclick=e=>{if(e.target.id==='modal')$('#modal').classList.remove('show')};
log('A República de Aurora observa a crescente tensão no continente.');renderAll();setInterval(()=>{if(speed===1)tick();else if(speed===2){tick();setTimeout(()=>{if(speed===2)tick()},360)}},1500);
</script></body></html>

