 <!DOCTYPE html>
 <html lang="pt-BR"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Fronteiras — 1936</title><style>
+@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Playfair+Display:wght@600;700&display=swap');
+:root{--bg:#101617;--panel:#192122;--line:#34403d;--muted:#91a09a;--text:#e9ece3;--gold:#e4b75d;--red:#d66b5b;--sans:'DM Sans',sans-serif;--mono:'DM Mono',monospace;--serif:'Playfair Display',serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font-family:var(--sans);min-height:100vh;overflow:hidden}button{font:inherit;color:inherit;cursor:pointer}#app{height:100vh;min-height:650px;display:flex;flex-direction:column;background:radial-gradient(ellipse at 42% 52%,#202c2b,#111819 63%)}
+.topbar{height:68px;display:flex;align-items:center;padding:0 26px;border-bottom:1px solid #303a38;background:#12191a;gap:26px;flex-shrink:0;z-index:5}.brand{display:flex;align-items:center;gap:11px;min-width:208px}.brand-mark{width:34px;height:34px;border:1px solid var(--gold);border-radius:50%;display:grid;place-items:center;color:var(--gold);font:20px var(--serif);box-shadow:inset 0 0 0 4px #18201e}.brand-name{font:18px var(--serif);letter-spacing:.08em}.brand-sub{font-size:9px;color:#85918c;letter-spacing:.2em;text-transform:uppercase;margin-top:1px}.top-sep{height:30px;width:1px;background:#34403d}.datebox{display:flex;flex-direction:column;gap:2px;min-width:130px}.date-label,.eyebrow{font:9px var(--mono);text-transform:uppercase;letter-spacing:.16em;color:#9daaa2}.date{font:17px var(--serif);color:#f1eee0}.top-stats{display:flex;align-items:center;gap:22px;margin-left:10px}.stat{display:flex;align-items:center;gap:8px;color:#d9dfd8;font:12px var(--mono)}.stat-icon{font-size:15px;color:var(--gold)}.stat small{display:block;color:#82908a;font-size:8px;letter-spacing:.1em;margin-top:2px}.top-right{margin-left:auto;display:flex;align-items:center;gap:9px}.speed-label{font:9px var(--mono);color:#91a09a;text-transform:uppercase}.icon-btn,.speed-btn,.pause-btn{border:1px solid #3a4742;background:#1a2222;border-radius:4px;height:34px;min-width:35px;color:#aab5ac}.speed-btn{font:11px var(--mono);padding:0 11px}.speed-btn.active{color:var(--gold);border-color:#987c48;background:#2c281e}.pause-btn{padding:0 13px;color:var(--text);font-size:11px}.pause-btn:hover,.speed-btn:hover{border-color:var(--gold)}
