const monthNames=['JANEIRO','FEVEREIRO','MARÇO','ABRIL','MAIO','JUNHO','JULHO','AGOSTO','SETEMBRO','OUTUBRO','NOVEMBRO','DEZEMBRO'];
const player=()=>nations.aurora;
const province=id=>provinces.find(p=>p.id===id);
function addLog(text,alert=false){logs.unshift({day:dateDay,month:dateMonth,text,alert});logs=logs.slice(0,7);renderLog()}
function renderLog(){$('#logList').innerHTML=logs.map(l=>`<div class="log-item ${l.alert?'alert':''}"><span class="log-date">${l.day} ${monthNames[l.month].slice(0,3)}</span><span>${l.text}</span></div>`).join('')}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100)}
function renderHeader(){$('#date').textContent=`${dateDay} ${monthNames[dateMonth]} ${dateYear}`;$('#industry').textContent=player().industry;$('#manpower').textContent=player().manpower;$('#research').textContent=player().research;$('#warStatus').textContent=wars.some(w=>w.includes('aurora'))?'EM GUERRA':'PAZ'}
function renderProvince(){const p=province(selected);if(!p){$('#sideContent').innerHTML='<div class="empty-state">Selecione uma província no mapa para ver seus detalhes.</div>';return}const n=nations[p.owner],owned=p.owner==='aurora',hasEnemyNeighbor=provinces.some(q=>q.owner!==p.owner&&isWar(p.owner,q.owner)&&adjacent(p,q));let buttons='';if(owned){buttons+=`<button class="action-btn primary" id="recruit" ${player().manpower<5||player().industry<2?'disabled':''}><span>♟ Recrutar unidade</span><span class="action-hint">5 reservas · 2 produção</span></button>`;if(hasEnemyNeighbor)buttons+=`<button class="action-btn danger" id="attackToggle"><span>${attackMode?'Cancelar ofensiva':'⚔ Planejar ofensiva'}</span><span class="action-hint">Escolha vizinho inimigo</span></button>`}else if(isWar('aurora',p.owner)&&attackMode){buttons='<button class="action-btn danger" id="attackTarget"><span>⚔ Atacar esta província</span><span class="action-hint">Ordem de combate</span></button>'}else if(!isWar('aurora',p.owner)){buttons='<div class="action-hint" style="padding:8px">Não há estado de guerra com esta nação. Use a aba Nação para declarar guerra.</div>'}$('#sideContent').innerHTML=`<div class="faction-banner"><div class="flag" style="background:${n.color}">${n.flag}</div><div><div class="banner-title">${p.name}</div><div class="banner-sub">${n.name.toUpperCase()}</div></div></div><div class="selected-card" style="margin-top:13px"><div class="selected-head"><div><div class="province-name">${p.city}</div><div class="province-meta">Centro urbano · ${p.name}</div></div><span class="owner-pill">${n.short}</span></div><div class="province-stats"><div class="p-stat"><span>Unidades</span><strong>♟ ${p.units}</strong></div><div class="p-stat"><span>Fábricas</span><strong>⚙ ${p.factories}</strong></div><div class="p-stat"><span>População mobilizável</span><strong>${p.manpower}</strong></div><div class="p-stat"><span>Posição</span><strong>${p.col+1} · ${p.row+1}</strong></div></div><div class="actions">${buttons}</div></div><div class="section-title">Estado da província</div><div class="province-meta">${owned?'Sob seu controle.':'Território estrangeiro.'} ${isWar('aurora',p.owner)?'A linha de frente está ativa.':'A paz prevalece nesta fronteira.'}</div>`;$('#recruit')?.addEventListener('click',recruit);$('#attackToggle')?.addEventListener('click',()=>{attackMode=!attackMode;toast(attackMode?'Selecione uma província inimiga adjacente.':'Ofensiva cancelada.');render()});$('#attackTarget')?.addEventListener('click',()=>queueAttack(p))}
function renderNation(){const id=focus||'aurora',n=nations[id],territory=ownProvinces(id),atWar=wars.some(w=>w.includes(id));$('#sideContent').innerHTML=`<div class="faction-banner"><div class="flag" style="background:${n.color}">${n.flag}</div><div><div class="banner-title">${n.name}</div><div class="banner-sub">${id==='aurora'?'NAÇÃO DO JOGADOR':'POTÊNCIA EDRIANA'}</div></div></div><div class="country-overview"><div class="overview-cell"><div class="overview-num">${territory.length}</div><div class="overview-label">Províncias</div></div><div class="overview-cell"><div class="overview-num">${territory.reduce((s,p)=>s+p.units,0)}</div><div class="overview-label">Unidades</div></div><div class="overview-cell"><div class="overview-num">${n.stability}%</div><div class="overview-label">Estabilidade</div></div></div><div class="section-title">Recursos nacionais</div><div class="province-stats"><div class="p-stat"><span>Produção disponível</span><strong>⚙ ${n.industry}</strong></div><div class="p-stat"><span>Reservas humanas</span><strong>♟ ${n.manpower}</strong></div><div class="p-stat"><span>Conhecimento</span><strong>◈ ${n.research}</strong></div><div class="p-stat"><span>Estado diplomático</span><strong>${atWar?'GUERRA':'PAZ'}</strong></div></div><div class="section-title">Diplomacia</div>${id==='aurora'?Object.entries(nations).filter(([other])=>other!=='aurora').map(([other,enemy])=>{const war=isWar('aurora',other);return `<div class="selected-card" style="margin-bottom:8px"><div class="selected-head"><div><div class="province-name" style="font-size:15px">${enemy.name}</div><div class="province-meta">${ownProvinces(other).length} províncias · ${war?'Em guerra':'Relações tensas'}</div></div><span class="owner-pill" style="border-color:${enemy.color}">${war?'GUERRA':'PAZ'}</span></div><div class="actions"><button class="action-btn ${war?'':'danger'}" data-war="${other}" ${war?'disabled':''}><span>${war?'Campanha em andamento':'Declarar guerra'}</span><span class="action-hint">${war?'':''}</span></button></div></div>`}).join(''):`<div class="empty-state">Você está observando ${n.short}. Selecione Aurora na aba Nação para conduzir a diplomacia.</div>`}<div class="section-title">Ordens ativas</div><div class="province-meta">${orders.filter(o=>o.attacker==='aurora').length?orders.filter(o=>o.attacker==='aurora').map(o=>`${province(o.from)?.name} → ${province(o.to)?.name}`).join('<br>'):'Nenhuma ofensiva em andamento.'}</div>`;document.querySelectorAll('[data-war]').forEach(b=>b.addEventListener('click',()=>declareWar(b.dataset.war)))}
function renderResearch(){const n=player();$('#sideContent').innerHTML=`<div class="faction-banner"><div class="flag">◈</div><div><div class="banner-title">Modernização</div><div class="banner-sub">PROGRESSO CIENTÍFICO · ${n.research} PONTOS</div></div></div><div class="section-title">Projetos disponíveis</div>${researchTechs.map(t=>{const done=researched.includes(t.id);return `<div class="research-card"><div class="research-icon">${t.icon}</div><div class="research-info"><strong>${t.name}</strong><small>${t.desc} · Custo ${t.cost}◈</small></div><button data-tech="${t.id}" ${done||n.research<t.cost?'disabled':''}>${done?'Concluído':'Pesquisar'}</button></div>`}).join('')}<div class="province-meta" style="margin-top:14px">O conhecimento cresce mensalmente. Invista para desbloquear vantagens permanentes.</div>`;document.querySelectorAll('[data-tech]').forEach(b=>b.addEventListener('click',()=>researchTech(b.dataset.tech)))}
function render(){renderHeader();renderMap();if(activeTab==='province')renderProvince();else if(activeTab==='nation')renderNation();else renderResearch()}
function onProvince(id){if(attackMode){const p=province(id),src=province(selected);if(p&&src&&p.owner!=='aurora'&&isWar('aurora',p.owner)&&adjacent(src,p)){selected=id;render();return}}selected=id;if(activeTab!=='province')activeTab='province';document.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===activeTab));render()}
function recruit(){const p=province(selected);if(!p||p.owner!=='aurora'||player().manpower<5||player().industry<2)return;p.units++;player().manpower-=5;player().industry-=2;addLog(`Uma unidade foi mobilizada em ${p.name}.`);render()}
function declareWar(id){if(id==='aurora'||isWar('aurora',id))return;wars.push(['aurora',id]);attackMode=false;addLog(`Aurora declarou guerra a ${nations[id].name}.`,true);toast('A guerra começou. Mobilize suas forças!');render()}
function queueAttack(target){const from=province(selected);if(!from||from.owner!=='aurora'||target.owner==='aurora'||!isWar('aurora',target.owner)||!adjacent(from,target)||from.units<1)return;if(orders.some(o=>o.from===from.id))return toast('Esta província já possui uma ordem.');orders.push({from:from.id,to:target.id,attacker:'aurora',progress:0});attackMode=false;addLog(`Ofensiva iniciada de ${from.name} em direção a ${target.name}.`,true);render()}
function researchTech(id){const t=researchTechs.find(x=>x.id===id);if(!t||researched.includes(id)||player().research<t.cost)return;player().research-=t.cost;researched.push(id);if(id==='industria')player().industry+=5;if(id==='doutrina')player().defense=1.25;if(id==='logistica')player().logistics=1.15;addLog(`Pesquisa concluída: ${t.name}.`);toast(`${t.name} concluída`);render()}
function advanceDate(){dateDay++;tickCount++;if(dateDay>30){dateDay=1;dateMonth++;if(dateMonth>11){dateMonth=0;dateYear++}player().industry+=3;player().research+=1;player().manpower+=2;Object.values(nations).filter(n=>n!==player()).forEach(n=>{n.industry+=3;n.manpower+=2});addLog(`Novo mês: produção e reservas foram renovadas.`)}orders.slice().forEach(order=>{order.progress++;if(order.progress>=3){const from=province(order.from),to=province(order.to);if(!from||!to||from.owner!=='aurora'||!isWar('aurora',to.owner)){orders=orders.filter(o=>o!==order);return}const attack=from.units*(player().logistics||1)*(0.85+Math.random()*.45),defense=Math.max(1,to.units)*(to.owner==='aurora'?(player().defense||1):1)*(0.8+Math.random()*.5);if(attack>defense){to.owner='aurora';to.units=Math.max(1,Math.floor(from.units/2));from.units=Math.max(1,from.units-to.units);player().stability=Math.min(100,player().stability+2);addLog(`Vitória em ${to.name}; a província foi ocupada.`)}else{from.units=Math.max(0,from.units-1);to.units=Math.max(1,to.units-1);addLog(`A ofensiva em ${to.name} foi repelida.`,true)}orders=orders.filter(o=>o!==order);const enemy=to.owner==='aurora'?order.to===to.id?Object.entries(nations).find(([nid])=>nid!=='aurora'&&ownProvinces(nid).length===0)?.[0]:null:null;if(enemy)wars=wars.filter(w=>!w.includes(enemy));checkEnd()}});render()}
function checkEnd(){const own=ownProvinces('aurora').length;if(own===0){gameOver(false);return}const remaining=Object.keys(nations).filter(id=>id!=='aurora'&&ownProvinces(id).length);if(!remaining.length)gameOver(true)}
function gameOver(win){gameEnded=true;$('#endingTitle').textContent=win?'Vitória':'Derrota';$('#endingText').textContent=win?'Aurora unificou Edria sob sua bandeira. A história do continente será escrita por sua república.':'Aurora perdeu todas as suas províncias. A campanha termina, mas a história de Edria continua.';$('#gameover').classList.add('show');speed=0;document.querySelectorAll('.speed-btn').forEach(b=>b.classList.toggle('active',b.dataset.speed==='0'))}
let timer=null;function setSpeed(value){speed=Number(value);document.querySelectorAll('.speed-btn').forEach(b=>b.classList.toggle('active',Number(b.dataset.speed)===speed));$('#pause').textContent=speed===0?'Retomar':'Pausar';clearInterval(timer);if(speed>0&&!gameEnded)timer=setInterval(advanceDate,speed===1?1500:650)}
document.querySelectorAll('.tab').forEach(t=>t.addEventListener('click',()=>{activeTab=t.dataset.tab;document.querySelectorAll('.tab').forEach(x=>x.classList.toggle('active',x===t));render()}));document.querySelectorAll('.speed-btn').forEach(b=>b.addEventListener('click',()=>setSpeed(b.dataset.speed)));$('#pause').addEventListener('click',()=>setSpeed(speed===0?1:0));$('#mapMode').addEventListener('click',e=>{e.currentTarget.classList.toggle('active');renderMap()});$('#labelsToggle').addEventListener('click',e=>{labelsOn=!labelsOn;e.currentTarget.classList.toggle('active',labelsOn);renderMap()});$('#closeModal').addEventListener('click',()=>$('#modal').classList.remove('show'));$('#modal').addEventListener('click',e=>{if(e.target.id==='modal')$('#modal').classList.remove('show')});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#modal').classList.remove('show');attackMode=false;render()}});
addLog('A República de Aurora observa com cautela as fronteiras de Edria.');addLog('O outono começa; as potências reforçam suas posições.');render();setSpeed(1);
